mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM teams
    WHERE team_code = #{teamCode}
      AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
)

mapper.update:
UPDATE teams
SET team_name = #{team.teamName},
    department_code = #{team.departmentCode},
    updated_at = CURRENT_TIMESTAMP
WHERE team_code = #{teamCode}
  AND delete_flag = ${@com.uit.sociusmvcapp.shared.enums.DeleteFlagEnums@NOT_DELETED.value}
